 func (m *BuntDBManager) GetAllKeysWithPrefix(prefix string) ([]string, error) {
 	m.mu.RLock()
 	defer m.mu.RUnlock()

 	var keys []string
 	err := m.db.View(func(tx *buntdb.Tx) error {
 		return tx.Ascend(prefix+"*", func(key, value string) bool {
 			keys = append(keys, key)
 			return true
 		})
 	})

 	return keys, err
 }

