package embeddings

import (
	"math"
	"strings"
)

// DeterministicService provides reproducible embeddings without external dependencies.
type DeterministicService struct {
	batchSize int
}

// DefaultBatchSize is the default batch size for embedding requests.
const DefaultBatchSize = 32

// NewDeterministicService creates a new deterministic embedding service.
func NewDeterministicService() *DeterministicService {
	return &DeterministicService{
		batchSize: DefaultBatchSize,
	}
}

// GetEmbedding returns a deterministic embedding vector for the given text.
// Uses a hash-based approach that produces the same vector for the same input.
func (s *DeterministicService) GetEmbedding(text string) []float32 {
	clean := strings.ToLower(strings.TrimSpace(text))
	embedding := make([]float32, 768)

	if len(clean) == 0 {
		return embedding
	}

	// Generate deterministic embedding using character hashing
	for i, r := range clean {
		idx := int(r) % 768
		embedding[idx] += float32(int(r) * (float32(i%7) + 1.0)
	}

	// Normalize to unit vector
	var norm float32
	for _, v := range embedding {
		norm += v * v
	}
	if norm > 0 {
		norm = float32(math.Sqrt(float64(norm)))
		for i := range embedding {
			embedding[i] /= norm
		}
	}

	return embedding
}

// GetBatchEmbeddings returns embeddings for a batch of texts.
func (s *DeterministicService) GetBatchEmbeddings(texts []string) [][]float32 {
	if len(texts) == 0 {
		return nil
	}

	embeddings := make([][]float32, len(texts))
	for i, text := range texts {
		embeddings[i] = s.GetEmbedding(text)
	}
	return embeddings
}

// CosineSimilarity computes the cosine similarity between two vectors.
func CosineSimilarity(a, b []float32) float32 {
	if len(a) != len(b) || len(a) == 0 {
		return 0.0
	}

	var dot, normA, normB float32
	for i := range a {
		dot += a[i] * b[i]
		normA += a[i] * a[i]
		normB += b[i] * b[i]
	}

	if normA == 0 || normB == 0 {
		return 0.0
	}

	return dot / (float32(math.Sqrt(float64(normA))) * float32(math.Sqrt(float64(normB))))
}

// GetBatchSize returns the configured batch size.
func (s *DeterministicService) GetBatchSize() int {
	return s.batchSize
}

